package canteen;
import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.sql.*;
public class StockManagementFrame extends JFrame {
 private final String user,role; private JTable table;private DefaultTableModel model;private JTextField search;
 public StockManagementFrame(String user,String role){this.user=user;this.role=role;if(!AuditLog.isAdmin(role)){AuditLog.requireAdmin(null,role);dispose();return;}AppStyle.setWindowIcon(this);setTitle("PIET | Stock Management");setSize(1050,650);setLocationRelativeTo(null);JPanel p=AppStyle.page("Stock management");JPanel top=new JPanel(new FlowLayout(FlowLayout.LEFT));top.setOpaque(false);search=new JTextField(18);JButton find=AppStyle.button("Search",AppStyle.BLUE),refresh=AppStyle.button("Refresh",AppStyle.NAVY),adjust=AppStyle.button("Adjust stock",new Color(25,145,112)),threshold=AppStyle.button("Set min. threshold",new Color(126,83,190)),history=AppStyle.button("Movement history",new Color(200,125,30));top.add(new JLabel("Food name/category:"));top.add(search);top.add(find);top.add(refresh);top.add(adjust);top.add(threshold);top.add(history);model=new DefaultTableModel(new String[]{"ID","Food","Category","Stock","Minimum","Status"},0){public boolean isCellEditable(int r,int c){return false;}};table=new JTable(model);AppStyle.styleTable(table);JPanel center=new JPanel(new BorderLayout(8,8));center.setOpaque(false);center.add(top,BorderLayout.NORTH);center.add(new JScrollPane(table),BorderLayout.CENTER);p.add(center,BorderLayout.CENTER);find.addActionListener(e->load());refresh.addActionListener(e->{search.setText("");load();});adjust.addActionListener(e->adjust());threshold.addActionListener(e->threshold());history.addActionListener(e->showHistory());add(p);load();}
 private int selectedId(){int r=table.getSelectedRow();return r<0?-1:Integer.parseInt(model.getValueAt(table.convertRowIndexToModel(r),0).toString());}
 private void load(){model.setRowCount(0);String sql="SELECT item_id,item_name,category,stock_quantity,COALESCE(min_stock_threshold,10) min_stock FROM food_items WHERE item_name LIKE ? OR category LIKE ? ORDER BY item_name";try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement(sql)){s.setString(1,"%"+search.getText().trim()+"%");s.setString(2,"%"+search.getText().trim()+"%");try(ResultSet r=s.executeQuery()){while(r.next()){int q=r.getInt("stock_quantity"),m=r.getInt("min_stock");model.addRow(new Object[]{r.getInt("item_id"),r.getString("item_name"),r.getString("category"),q,m,q==0?"OUT OF STOCK":q<=m?"LOW STOCK":"IN STOCK"});}}}catch(SQLException e){error(e);}}
 private void adjust(){int id=selectedId();if(id<0){JOptionPane.showMessageDialog(this,"Select a food item first.");return;}JTextField amount=new JTextField("1"),reason=new JTextField();JComboBox<String> action=new JComboBox<>(new String[]{"Add stock","Reduce stock"});JPanel p=new JPanel(new GridLayout(0,1,5,5));p.add(new JLabel("Adjustment type"));p.add(action);p.add(new JLabel("Quantity"));p.add(amount);p.add(new JLabel("Reason (required)"));p.add(reason);if(JOptionPane.showConfirmDialog(this,p,"Confirm stock adjustment",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;try{int n=Integer.parseInt(amount.getText().trim());if(n<1||reason.getText().trim().isEmpty())throw new IllegalArgumentException();try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{int before;try(PreparedStatement s=c.prepareStatement("SELECT stock_quantity FROM food_items WHERE item_id=? FOR UPDATE")){s.setInt(1,id);try(ResultSet r=s.executeQuery()){if(!r.next())throw new SQLException("Food item not found");before=r.getInt(1);}}int after=action.getSelectedIndex()==0?before+n:before-n;if(after<0)throw new SQLException("Stock cannot become negative.");try(PreparedStatement s=c.prepareStatement("UPDATE food_items SET stock_quantity=?,available=(? > 0) WHERE item_id=?")){s.setInt(1,after);s.setInt(2,after);s.setInt(3,id);s.executeUpdate();}try(PreparedStatement s=c.prepareStatement("INSERT INTO stock_movements(item_id,previous_quantity,new_quantity,change_quantity,reason,username,created_at) VALUES(?,?,?,?,?,?,CURRENT_TIMESTAMP)")){s.setInt(1,id);s.setInt(2,before);s.setInt(3,after);s.setInt(4,after-before);s.setString(5,reason.getText().trim());s.setString(6,user);s.executeUpdate();}c.commit();AuditLog.record(user,"STOCK_ADJUSTED","Item "+id+" "+before+" -> "+after+"; "+reason.getText());}catch(Exception ex){c.rollback();throw ex;}finally{c.setAutoCommit(true);}}load();}catch(IllegalArgumentException e){JOptionPane.showMessageDialog(this,"Enter a positive quantity and a reason.");}catch(Exception e){error(e);}}
 private void threshold(){int id=selectedId();if(id<0){JOptionPane.showMessageDialog(this,"Select a food item first.");return;}String val=JOptionPane.showInputDialog(this,"Minimum stock threshold:",model.getValueAt(table.getSelectedRow(),4));if(val==null)return;try{int n=Integer.parseInt(val);if(n<0)throw new NumberFormatException();try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement("UPDATE food_items SET min_stock_threshold=? WHERE item_id=?")){s.setInt(1,n);s.setInt(2,id);s.executeUpdate();}AuditLog.record(user,"STOCK_THRESHOLD_CHANGED","Item "+id+" threshold="+n);load();}catch(Exception e){error(e);}}
 private void showHistory(){JTable t=new JTable();DefaultTableModel m=new DefaultTableModel(new String[]{"Date","Item","Previous","New","Change","Reason","User"},0);t.setModel(m);try(Connection c=DBConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT sm.created_at,fi.item_name,sm.previous_quantity,sm.new_quantity,sm.change_quantity,sm.reason,sm.username FROM stock_movements sm LEFT JOIN food_items fi ON fi.item_id=sm.item_id ORDER BY sm.created_at DESC LIMIT 500")){while(r.next())m.addRow(new Object[]{r.getTimestamp(1),r.getString(2),r.getInt(3),r.getInt(4),r.getInt(5),r.getString(6),r.getString(7)});}catch(SQLException e){error(e);return;}AppStyle.styleTable(t);JOptionPane.showMessageDialog(this,new JScrollPane(t),"Stock movement history (latest 500)",JOptionPane.PLAIN_MESSAGE);}
 private void error(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Stock error",JOptionPane.ERROR_MESSAGE);}
}
